-- CockroachDB multi-region table locality
ALTER TABLE customers ADD COLUMN region crdb_internal_region;
ALTER TABLE customers CONFIGURE ZONE USING num_replicas = 3;

CREATE TABLE telemetry (
    device_id VARCHAR(50),
    recorded_at TIMESTAMPTZ NOT NULL,
    payload JSONB
) PARTITION BY RANGE (recorded_at);

CREATE TABLE telemetry_2026_11 PARTITION OF telemetry
    FOR VALUES FROM ('2026-11-01') TO ('2026-12-01');

-- Enforce consistent resource lock ordering across transactions
-- Always lock accounts in ascending order of ID
SELECT * FROM accounts WHERE id IN (10, 20) ORDER BY id FOR UPDATE;

CREATE EXTENSION postgres_fdw;
CREATE SERVER foreign_billing FOREIGN DATA WRAPPER postgres_fdw 
  OPTIONS (host 'billing-db.dataradix.in', dbname 'billing');
IMPORT FOREIGN SCHEMA public FROM SERVER foreign_billing INTO foreign_billing_schema;

